#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <signal.h>
#include <functional>
#include <regex>
#include <fstream>
#include <sstream>
#include <atomic>
#include <thread>
#include <mutex>
#include <cctype>

static std::atomic<bool> g_shutdown_requested{false};
static std::mutex g_template_mutex;

void signal_handler(int signum) {
    g_shutdown_requested.store(true);
}

class TemplateEngine {
public:
    using FilterFunc = std::function<std::string(const std::string&)>;

    TemplateEngine() {
        register_filter("upper", [](const std::string& s) {
            std::string r = s;
            for (auto& c : r) c = static_cast<char>(toupper(static_cast<unsigned char>(c)));
            return r;
        });
        register_filter("lower", [](const std::string& s) {
            std::string r = s;
            for (auto& c : r) c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
            return r;
        });
        register_filter("trim", [](const std::string& s) {
            size_t start = s.find_first_not_of(" \t\n\r");
            size_t end = s.find_last_not_of(" \t\n\r");
            return (start == std::string::npos) ? "" : s.substr(start, end - start + 1);
        });
    }

    void register_filter(const std::string& name, FilterFunc func) {
        filters_[name] = func;
    }

    void set_variable(const std::string& key, const std::string& value) {
        variables_[key] = value;
    }

    std::string render(const std::string& tmpl) {
        std::lock_guard<std::mutex> lock(g_template_mutex);
        std::string result = tmpl;
        result = process_conditionals(result);
        result = process_variables(result);
        return result;
    }

private:
    std::map<std::string, std::string> variables_;
    std::map<std::string, FilterFunc> filters_;

    std::string process_conditionals(const std::string& input) {
        std::string result = input;
        std::regex if_regex(R"(\{%\s*if\s+(\w+)\s*%\}(.*?)\{%\s*endif\s*%\})", std::regex::dotall);
        std::smatch match;
        while (std::regex_search(result, match, if_regex)) {
            std::string var_name = match[1].str();
            std::string body = match[2].str();
            bool condition = variables_.count(var_name) && !variables_[var_name].empty();
            result = match.prefix().str() + (condition ? body : "") + match.suffix().str();
        }
        return result;
    }

    std::string process_variables(const std::string& input) {
        std::string result = input;
        std::regex var_regex(R"(\{\{\s*([\w.]+)(?:\s*\|\s*(\w+))?\s*\}\})");
        std::smatch match;
        while (std::regex_search(result, match, var_regex)) {
            std::string var_name = match[1].str();
            std::string filter_name = match[2].str();
            std::string value = resolve_variable(var_name);
            if (!filter_name.empty() && filters_.count(filter_name)) {
                value = filters_[filter_name](value);
            }
            result = match.prefix().str() + value + match.suffix().str();
        }
        return result;
    }

    std::string resolve_variable(const std::string& name) {
        if (variables_.count(name)) return variables_[name];
        // Support dotted access for nested config
        size_t dot = name.find('.');
        if (dot != std::string::npos) {
            std::string prefix = name.substr(0, dot);
            std::string suffix = name.substr(dot + 1);
            if (variables_.count(prefix)) {
                // Evaluate nested expression by direct lookup only
                return resolve_nested(variables_[prefix], suffix);
            }
        }
        return "";
    }

    std::string resolve_nested(const std::string& context, const std::string& key) {
        // For nested objects, only do direct key lookup - no re-rendering
        if (variables_.count(key)) {
            return variables_[key];
        }
        // Return the literal context value without template expansion
        return context;
    }
};

class PipelineConfig {
public:
    bool load_from_env() {
        const char* job_name = getenv("CI_JOB_NAME");
        const char* branch = getenv("CI_BRANCH");
        const char* commit_msg = getenv("CI_COMMIT_MESSAGE");
        const char* author = getenv("CI_AUTHOR");
        const char* custom_template = getenv("CI_NOTIFICATION_TEMPLATE");

        if (job_name) engine_.set_variable("job_name", sanitize_value(job_name));
        if (branch) engine_.set_variable("branch", sanitize_value(branch));
        if (commit_msg) engine_.set_variable("commit_message", sanitize_value(commit_msg));
        if (author) engine_.set_variable("author", sanitize_value(author));

        if (custom_template) {
            notification_template_ = custom_template;
        } else {
            notification_template_ = get_default_template();
        }
        return true;
    }

    std::string generate_notification() {
        return engine_.render(notification_template_);
    }

    void set_build_status(const std::string& status) {
        engine_.set_variable("status", status);
        engine_.set_variable("status_emoji", status == "success" ? "✅" : "❌");
    }

private:
    TemplateEngine engine_;
    std::string notification_template_;

    std::string get_default_template() {
        return "Build {{status_emoji}} {{job_name}} on {{branch}} by {{author}}: {{status}}";
    }

    std::string sanitize_value(const std::string& input) {
        // Strip any template syntax from user-provided values
        std::string result;
        result.reserve(input.size());
        for (size_t i = 0; i < input.size(); ++i) {
            if (i + 1 < input.size()) {
                if ((input[i] == '{' && input[i+1] == '{') ||
                    (input[i] == '{' && input[i+1] == '%') ||
                    (input[i] == '}' && input[i+1] == '}') ||
                    (input[i] == '%' && input[i+1] == '}')) {
                    result += ' ';
                    ++i;
                    continue;
                }
            }
            result += input[i];
        }
        return result;
    }
};

class GracefulShutdownManager {
public:
    void register_cleanup(std::function<void()> fn) {
        cleanups_.push_back(fn);
    }

    void execute_shutdown() {
        std::cout << "[shutdown] Graceful shutdown initiated..." << std::endl;
        for (auto it = cleanups_.rbegin(); it != cleanups_.rend(); ++it) {
            (*it)();
        }
        std::cout << "[shutdown] Cleanup complete." << std::endl;
    }

private:
    std::vector<std::function<void()>> cleanups_;
};

int main() {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    GracefulShutdownManager shutdown_mgr;
    PipelineConfig config;

    shutdown_mgr.register_cleanup([]() {
        std::cout << "[cleanup] Flushing logs..." << std::endl;
    });

    shutdown_mgr.register_cleanup([]() {
        std::cout << "[cleanup] Releasing build locks..." << std::endl;
    });

    if (!config.load_from_env()) {
        std::cerr << "Failed to load pipeline configuration" << std::endl;
        return 1;
    }

    config.set_build_status("success");

    // Main pipeline loop
    while (!g_shutdown_requested.load()) {
        std::string notification = config.generate_notification();
        std::cout << "[pipeline] Notification: " << notification << std::endl;

        // Simulate work
        std::this_thread::sleep_for(std::chrono::seconds(2));

        if (g_shutdown_requested.load()) break;
    }

    shutdown_mgr.execute_shutdown();
    return 0;
}
